<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ValueObject\ThemeVersionChannelVO;
use Civi\Lughauth\Features\Document\ThemeVersion\Domain\ThemeVersionChannelOptions;

final class ThemeVersionChannelVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = ThemeVersionChannelOptions::MAIL;
        $ref = ThemeVersionChannelVO::from($value);
        $this->assertEquals(ThemeVersionChannelOptions::MAIL, $ref->value());
        $other = ThemeVersionChannelVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = ThemeVersionChannelVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = ThemeVersionChannelVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(ThemeVersionChannelVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = ThemeVersionChannelVO::from(ThemeVersionChannelOptions::MAIL);
        $same = ThemeVersionChannelVO::from(ThemeVersionChannelOptions::MAIL);
        $other = ThemeVersionChannelVO::from(ThemeVersionChannelOptions::HTML);
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
}
